package com.nivor.workspace;
import com.nivor.common.exception.ResourceNotFoundException;import com.nivor.project.ProjectRepository;import com.nivor.user.*;import com.nivor.workspace.dto.WorkspaceRequest;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class WorkspaceService{
private final WorkspaceRepository workspaces;private final UserService users;private final ProjectRepository projects;public WorkspaceService(WorkspaceRepository w,UserService u,ProjectRepository p){workspaces=w;users=u;projects=p;}
@Transactional(readOnly=true)public List<Workspace> list(String email){return workspaces.findAllByUser_IdOrderByNameAsc(users.getByEmail(email).getId());}@Transactional(readOnly=true)public Workspace get(String email,Long id){return owned(email,id);}@Transactional public Workspace create(String email,WorkspaceRequest r){Workspace w=new Workspace();w.setUser(users.getByEmail(email));apply(w,r);return workspaces.save(w);}@Transactional public Workspace update(String email,Long id,WorkspaceRequest r){Workspace w=owned(email,id);apply(w,r);return w;}@Transactional public void delete(String email,Long id){Workspace w=owned(email,id);projects.clearWorkspaceForUser(w.getId(),w.getUser().getId());workspaces.delete(w);}
private Workspace owned(String email,Long id){return workspaces.findByIdAndUser_Id(id,users.getByEmail(email).getId()).orElseThrow(()->new ResourceNotFoundException("Workspace not found"));}private void apply(Workspace w,WorkspaceRequest r){w.setName(r.name().trim());w.setDescription(r.description());}
}
